    t.badSoft = mix(r.bad, r.text, 0.5); t.badDeep = mix(r.bad, r.bg, 0.55); t.badDeeper = mix(r.bad, r.bg, 0.75);
    t.goodSoft = mix(r.good, r.text, 0.6); t.goodDeep = mix(r.good, r.bg, 0.6); t.accent2Deep = mix(r.accent2, r.bg, 0.75);
    return t;
